    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      cart.add(mkProduct("a", 1000), 1);
      expect(() => cart.updateQuantity("a", 1.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("removes all items", () => {
      const cart = new Cart();
      cart.add(mkProduct("a", 1000), 2);
      cart.add(mkProduct("b", 2000), 3);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy of cart lines", () => {
      const cart = new Cart();
      const product = mkProduct("a", 1000);
      cart.add(product, 2);
      const snap = cart.snapshot();
      expect(snap).toHaveLength(1);
      expect(snap[0].product.id).toBe("a");
      expect(snap[0].quantity).toBe(2);

      // Mutating snapshot should not affect cart
      (snap[0] as { quantity: number }).quantity = 99;
      expect(cart.itemCount).toBe(2);
    });
  });

  describe("totals — pricing pipeline", () => {
    it("computes subtotal as sum of unitPriceCents * quantity", () => {
      const cart = new Cart();
      cart.add(mkProduct("a", 1000), 2); // 2000
      cart.add(mkProduct("b", 500), 3); // 1500
      const t = cart.totals();
      expect(t.subtotalCents).toBe(3500);
    });

    it("returns all zeros for empty cart", () => {
      const cart = new Cart();
      const t = cart.totals();
      expect(t).toEqual({
        subtotalCents: 0,
        discountCents: 0,
        taxCents: 0,
        shippingCents: 0,
        totalCents: 0,
      });
    });

    it("applies discount → tax on discounted subtotal → shipping", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(500),
      };
      const tax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(150),
      };
      const shipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(300),
      };

      const cart = new Cart({
        discountPolicy: discount,
        taxCalculator: tax,
        shippingCalculator: shipping,
        region: "US-CA",
      });
      cart.add(mkProduct("a", 1000), 2); // subtotal 2000

      const t = cart.totals();

      // Discount applied to subtotal
      expect(discount.computeDiscountCents).toHaveBeenCalledWith(2000);
      expect(t.discountCents).toBe(500);

      // Tax on discounted subtotal (2000 - 500 = 1500)
      expect(tax.computeTaxCents).toHaveBeenCalledWith(1500, "US-CA");
      expect(t.taxCents).toBe(150);

      // Shipping on discounted subtotal
      expect(shipping.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        1500,
      );
      expect(t.shippingCents).toBe(300);

      // total = discountedSubtotal + tax + shipping = 1500 + 150 + 300
      expect(t.totalCents).toBe(1950);
    });

    it("clamps discount to [0, subtotal]", () => {
      // Discount exceeds subtotal
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(99999),
      };
      const cart = new Cart({ discountPolicy: discount });
      cart.add(mkProduct("a", 1000), 1);
      const t = cart.totals();
      expect(t.discountCents).toBe(1000); // clamped to subtotal
      expect(t.totalCents).toBe(0);
    });

    it("clamps negative discount to 0", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(-500),
      };
      const cart = new Cart({ discountPolicy: discount });
      cart.add(mkProduct("a", 1000), 1);
      const t = cart.totals();
      expect(t.discountCents).toBe(0);
    });

    it("clamps negative tax to 0", () => {
      const tax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ taxCalculator: tax });
      cart.add(mkProduct("a", 1000), 1);
      const t = cart.totals();
      expect(t.taxCents).toBe(0);
    });

    it("clamps negative shipping to 0", () => {
      const shipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ shippingCalculator: shipping });
      cart.add(mkProduct("a", 1000), 1);
      const t = cart.totals();
      expect(t.shippingCents).toBe(0);
    });

    it("uses default seams when no config is provided", () => {
      const cart = new Cart();
      cart.add(mkProduct("a", 1000), 1);
      const t = cart.totals();
      // Defaults: NoDiscountPolicy(0), NoTaxCalculator(0), FreeShippingCalculator(0)
      expect(t.subtotalCents).toBe(1000);
      expect(t.discountCents).toBe(0);
      expect(t.taxCents).toBe(0);
      expect(t.shippingCents).toBe(0);
      expect(t.totalCents).toBe(1000);
    });
  });

  describe("checkout", () => {
    it("returns totals and lines without collaborators", async () => {
      const cart = new Cart();
      cart.add(mkProduct("a", 1000), 2);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(2000);
      expect(result.lines).toHaveLength(1);
      expect(result.lines[0].quantity).toBe(2);
    });

    describe("price refresh", () => {
      it("refreshes prices from PriceFetcher before computing totals", async () => {
        const cart = new Cart();
        cart.add(mkProduct("a", 1000), 2);

        const fetcher: PriceFetcher = {
          fetchPriceCents: vi.fn().mockResolvedValue(1500),
        };

        const result = await cart.checkout({ priceFetcher: fetcher });
        expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("a");
        expect(result.totals.subtotalCents).toBe(3000); // 1500 * 2
        expect(result.lines[0].product.unitPriceCents).toBe(1500);
      });

      it("propagates PriceFetcher failure", async () => {
        const cart = new Cart();
        cart.add(mkProduct("a", 1000), 1);

        const fetcher: PriceFetcher = {
          fetchPriceCents: vi
            .fn()
            .mockRejectedValue(new Error("price service down")),
        };

        await expect(cart.checkout({ priceFetcher: fetcher })).rejects.toThrow(
          "price service down",
        );
      });
    });

    describe("inventory check", () => {
      it("proceeds when inventory is available", async () => {
        const cart = new Cart();
        cart.add(mkProduct("a", 1000), 2);

        const checker: InventoryChecker = {
          check: vi.fn().mockResolvedValue({ available: true }),
        };

        const result = await cart.checkout({ inventoryChecker: checker });
        expect(checker.check).toHaveBeenCalledWith("a", 2);
        expect(result.totals.subtotalCents).toBe(2000);
      });

      it("throws InventoryError when item unavailable", async () => {
        const cart = new Cart();
        cart.add(mkProduct("a", 1000), 5);

        const checker: InventoryChecker = {
          check: vi.fn().mockResolvedValue({
            available: false,
            reason: "discontinued",
          }),
        };

        try {
          await cart.checkout({ inventoryChecker: checker });
          expect.fail("should have thrown");
        } catch (err) {
          expect(err).toBeInstanceOf(InventoryError);
          const invErr = err as InventoryError;
          expect(invErr.productId).toBe("a");
          expect(invErr.requested).toBe(5);
          expect(invErr.message).toBe("discontinued");
        }
      });

      it("throws InventoryError for partial-stock denial", async () => {
        const cart = new Cart();
        cart.add(mkProduct("a", 1000), 10);

        const checker: InventoryChecker = {
          check: vi.fn().mockResolvedValue({
            available: true,
            availableQuantity: 3,
          }),
        };

        try {
          await cart.checkout({ inventoryChecker: checker });
          expect.fail("should have thrown");
        } catch (err) {
          expect(err).toBeInstanceOf(InventoryError);
          const invErr = err as InventoryError;
          expect(invErr.productId).toBe("a");
          expect(invErr.requested).toBe(10);
          expect(invErr.available).toBe(3);
        }
      });

      it("checks inventory for each line and fails on first denial", async () => {
        const cart = new Cart();
        cart.add(mkProduct("a", 1000), 1);
        cart.add(mkProduct("b", 2000), 1);

        const checker: InventoryChecker = {
          check: vi
            .fn()
            .mockResolvedValueOnce({ available: true })
            .mockResolvedValueOnce({ available: false }),
        };

        await expect(
          cart.checkout({ inventoryChecker: checker }),
        ).rejects.toThrow(InventoryError);
        expect(checker.check).toHaveBeenCalledTimes(2);
      });
    });

    describe("async tax", () => {
      it("uses AsyncTaxRateProvider for tax computation", async () => {
        const discount: DiscountPolicy = {
          computeDiscountCents: vi.fn().mockReturnValue(200),
        };
        const shipping: ShippingCalculator = {
          computeShippingCents: vi.fn().mockReturnValue(500),
        };

        const cart = new Cart({
          discountPolicy: discount,
          shippingCalculator: shipping,
          region: "US-CA",
        });
        cart.add(mkProduct("a", 1000), 2); // subtotal 2000

        const asyncTaxProvider: AsyncTaxRateProvider = {
          getRate: vi.fn().mockResolvedValue(0.1),
        };

        const result = await cart.checkout({ asyncTaxProvider });

        // discount: 200, discounted subtotal: 1800
        // tax: 10% of 1800 = 180
        // shipping: 500
        expect(result.totals.subtotalCents).toBe(2000);
        expect(result.totals.discountCents).toBe(200);
        expect(result.totals.taxCents).toBe(180);
        expect(result.totals.shippingCents).toBe(500);
        expect(result.totals.totalCents).toBe(1800 + 180 + 500);
        expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
      });

      it("propagates async tax provider failure", async () => {
        const cart = new Cart();
        cart.add(mkProduct("a", 1000), 1);

        const asyncTaxProvider: AsyncTaxRateProvider = {
          getRate: vi
            .fn()
            .mockRejectedValue(new Error("tax service unavailable")),
        };

        await expect(
          cart.checkout({ asyncTaxProvider }),
        ).rejects.toThrow("tax service unavailable");
      });
    });

    describe("full pipeline with all collaborators", () => {
      it("refreshes prices, checks inventory, then computes async totals", async () => {
        const discount: DiscountPolicy = {
          computeDiscountCents: vi.fn().mockReturnValue(100),
        };
        const shipping: ShippingCalculator = {
          computeShippingCents: vi.fn().mockReturnValue(250),
        };
        const cart = new Cart({
          discountPolicy: discount,
          shippingCalculator: shipping,
          region: "FR",
        });
        cart.add(mkProduct("a", 1000), 2);

        const fetcher: PriceFetcher = {
          fetchPriceCents: vi.fn().mockResolvedValue(1200),
        };
        const checker: InventoryChecker = {
          check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
        };
        const asyncTaxProvider: AsyncTaxRateProvider = {
          getRate: vi.fn().mockResolvedValue(0.2),
        };

        const result = await cart.checkout({
          priceFetcher: fetcher,
          inventoryChecker: checker,
          asyncTaxProvider,
        });

        // refreshed price: 1200 * 2 = 2400
        expect(result.totals.subtotalCents).toBe(2400);
        // discount: 100, discounted: 2300
        expect(result.totals.discountCents).toBe(100);
        // tax: 20% of 2300 = 460
        expect(result.totals.taxCents).toBe(460);
        expect(result.totals.shippingCents).toBe(250);
        // total = 2300 + 460 + 250 = 3010
        expect(result.totals.totalCents).toBe(3010);
        expect(result.lines[0].product.unitPriceCents).toBe(1200);
      });
    });
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([0, 100, 999_99, -50])(
    "always returns 0 regardless of subtotal (%i)",
    (subtotal) => {
      expect(policy.computeDiscountCents(subtotal)).toBe(0);
    },
  );
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, 101, NaN, Infinity, -Infinity])(
      "rejects out-of-range percent %s",
      (percent) => {
        expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
      },
    );

    it.each([0, 50, 100])("accepts valid percent %i", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("computes 10% of 10000 as 1000", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(10000)).toBe(1000);
    });

    it("rounds down to nearest cent", () => {
      const policy = new PercentageDiscountPolicy(33);
      // 33% of 100 = 33.0
      expect(policy.computeDiscountCents(100)).toBe(33);
      // 33% of 101 = 33.33 → floor to 33
      expect(policy.computeDiscountCents(101)).toBe(33);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-500)).toBe(0);
    });

    it("100% discount equals subtotal", () => {
      const policy = new PercentageDiscountPolicy(100);
      expect(policy.computeDiscountCents(5000)).toBe(5000);
    });

    it("0% discount returns 0", () => {
      const policy = new PercentageDiscountPolicy(0);
      expect(policy.computeDiscountCents(5000)).toBe(0);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects negative amount", () => {
      expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
    });

    it("rejects non-integer amount", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts zero", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns full amount when subtotal exceeds it", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(1000)).toBe(500);
    });

    it("caps at subtotal when amount exceeds subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(2000);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("returns subtotal when amount equals subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(1000);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all child policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 10000 = 1000
          new FixedAmountDiscountPolicy(500), // 500
        ],
        "sum",
      );
      expect(composite.computeDiscountCents(10000)).toBe(1500);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(500)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("clamps negative child discount to 0 before summing", () => {
      // NoDiscountPolicy always returns 0, so no negative contribution
      const composite = new CompositeDiscountPolicy(
        [new NoDiscountPolicy(), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      expect(composite.computeDiscountCents(1000)).toBe(200);
    });

    it("defaults to sum mode when mode is omitted", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(500),
      ]);
      // sum: 10% of 10000 + 500 = 1500
      expect(composite.computeDiscountCents(10000)).toBe(1500);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 10000 = 1000, remaining 9000
          new FixedAmountDiscountPolicy(500), // min(500, 9000) = 500
        ],
        "chain",
      );
      // total discount = 1000 + 500 = 1500
      expect(composite.computeDiscountCents(10000)).toBe(1500);
    });

    it("ordering matters — larger discount first yields different result", () => {
      const composite1 = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(50), // 50% of 1000 = 500, remaining 500
          new PercentageDiscountPolicy(50), // 50% of 500 = 250
        ],
        "chain",
      );
      // total: 500 + 250 = 750
      expect(composite1.computeDiscountCents(1000)).toBe(750);
    });

    it("stops accumulating when remaining reaches 0", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(1000), // caps at 1000 (equals subtotal)
          new FixedAmountDiscountPolicy(500), // remaining is 0, min(500,0)=0
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});

