describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets list", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with zero upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 500 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: -1, costCents: 500 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with non-integer costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: 5.5 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 5000, costCents: 1200 },
      ],
      2000,
    );

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 for cart with zero-weight items", () => {
      expect(
        calc.computeShippingCents([mkLineNoWeight("a", 3)], 5000),
      ).toBe(0);
    });

    it("selects first bracket for weight within it", () => {
      // 250g item, 1 qty → 250g ≤ 500 → 300
      expect(calc.computeShippingCents([mkLine("a", 250, 1)], 5000)).toBe(300);
    });

    it("selects bracket at boundary (weight == upToGrams)", () => {
      // exactly 500g → 300
      expect(calc.computeShippingCents([mkLine("a", 500, 1)], 5000)).toBe(300);
    });

    it("selects next bracket when weight exceeds boundary", () => {
      // 501g → next bracket (≤2000) → 700
      expect(calc.computeShippingCents([mkLine("a", 501, 1)], 5000)).toBe(700);
    });

    it("selects highest bracket for weight at its boundary", () => {
      // 5000g → 1200
      expect(calc.computeShippingCents([mkLine("a", 5000, 1)], 5000)).toBe(1200);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      // 5001g → overflow → 2000
      expect(calc.computeShippingCents([mkLine("a", 5001, 1)], 5000)).toBe(2000);
    });

    it("uses highest bracket cost as overflow when overflowCostCents not set", () => {
      const calcNoOverflow = new WeightBasedShippingCalculator([
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 600 },
      ]);
      // 2000g > 1000 → fallback to last bracket cost = 600
      expect(
        calcNoOverflow.computeShippingCents([mkLine("a", 2000, 1)], 5000),
      ).toBe(600);
    });

    it("sums weight across multiple lines", () => {
      // line a: 300g * 2 = 600, line b: 400g * 1 = 400 → total 1000g ≤ 2000 → 700
      const lines = [mkLine("a", 300, 2), mkLine("b", 400, 1)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(700);
    });

    it("sorts brackets regardless of input order", () => {
      const unordered = new WeightBasedShippingCalculator([
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 500, costCents: 300 },
      ]);
      // 400g ≤ 500 → 300 (sorted correctly)
      expect(
        unordered.computeShippingCents([mkLine("a", 400, 1)], 5000),
      ).toBe(300);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import {
  InventoryError,
  refreshPrices,
  type PriceFetcher,
} from "../src/inventory.ts";
import type { CartLine } from "../src/product.ts";

describe("InventoryError", () => {
  it("exposes productId, requested, and available properties", () => {
    const err = new InventoryError("out of stock", "prod-1", 5, 2);
    expect(err.message).toBe("out of stock");
    expect(err.productId).toBe("prod-1");
    expect(err.requested).toBe(5);
    expect(err.available).toBe(2);
    expect(err.name).toBe("InventoryError");
    expect(err).toBeInstanceOf(Error);
  });

  it("supports undefined available", () => {
    const err = new InventoryError("gone", "prod-2", 3, undefined);
    expect(err.available).toBeUndefined();
  });
});

describe("refreshPrices", () => {
  const mkLines = (): CartLine[] => [
    {
      product: { id: "p1", name: "Widget", unitPriceCents: 100 },
      quantity: 2,
    },
    {
      product: { id: "p2", name: "Gadget", unitPriceCents: 200, weightGrams: 500 },
      quantity: 1,
    },
  ];

  it("updates unitPriceCents from fetcher", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi
        .fn()
        .mockResolvedValueOnce(150)
        .mockResolvedValueOnce(250),
    };
    const result = await refreshPrices(mkLines(), fetcher);
    expect(result).toHaveLength(2);
    expect(result[0].product.unitPriceCents).toBe(150);
    expect(result[0].quantity).toBe(2);
    expect(result[1].product.unitPriceCents).toBe(250);
    expect(result[1].product.weightGrams).toBe(500);
  });

  it("preserves product fields other than unitPriceCents", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(999),
    };
    const lines: CartLine[] = [
      {
        product: {
          id: "x",
          name: "X",
          unitPriceCents: 1,
          weightGrams: 300,
          currency: "EUR",
        },
        quantity: 1,
      },
    ];
    const result = await refreshPrices(lines, fetcher);
    expect(result[0].product.name).toBe("X");
    expect(result[0].product.weightGrams).toBe(300);
    expect(result[0].product.currency).toBe("EUR");
    expect(result[0].product.unitPriceCents).toBe(999);
  });

  it("throws RangeError for negative fetched price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(-1),
    };
    await expect(refreshPrices(mkLines(), fetcher)).rejects.toThrow(RangeError);
  });

  it("throws RangeError for non-integer fetched price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(10.5),
    };
    await expect(refreshPrices(mkLines(), fetcher)).rejects.toThrow(RangeError);
  });

  it("propagates fetcher rejection", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi
        .fn()
        .mockRejectedValue(new Error("service unavailable")),
    };
    await expect(refreshPrices(mkLines(), fetcher)).rejects.toThrow(
      "service unavailable",
    );
  });

  it("returns empty array for empty lines", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn(),
    };
    const result = await refreshPrices([], fetcher);
    expect(result).toEqual([]);
    expect(fetcher.fetchPriceCents).not.toHaveBeenCalled();
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

const mkProduct = (
  id: string,
  unitPriceCents: number,
  weightGrams?: number,
): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents,
  weightGrams,
});

describe("Cart", () => {
  describe("add", () => {
    it("adds a new product to the cart", () => {
      const cart = new Cart();
      cart.add(mkProduct("a", 1000), 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantity when adding the same product twice", () => {
      const cart = new Cart();
      cart.add(mkProduct("a", 1000), 2);
      cart.add(mkProduct("a", 1000), 3);
      expect(cart.itemCount).toBe(5);
    });

    it("rejects non-positive quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(mkProduct("a", 1000), 0)).toThrow(RangeError);
      expect(() => cart.add(mkProduct("a", 1000), -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(mkProduct("a", 1000), 1.5)).toThrow(RangeError);
    });

    it("rejects negative unitPriceCents", () => {
      const cart = new Cart();
      expect(() => cart.add(mkProduct("a", -1), 1)).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("removes an existing product and returns true", () => {
      const cart = new Cart();
      cart.add(mkProduct("a", 1000), 1);
      expect(cart.remove("a")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product id", () => {
      const cart = new Cart();
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity of existing product", () => {
      const cart = new Cart();
      cart.add(mkProduct("a", 1000), 2);
      cart.updateQuantity("a", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity set to 0", () => {
      const cart = new Cart();
      cart.add(mkProduct("a", 1000), 2);
      cart.updateQuantity("a", 0);
      expect(cart.itemCount).toBe(0);
    });

    it("throws for unknown product id", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("nonexistent", 1)).toThrow(
        "Product nonexistent is not in the cart",
      );
    });

    it("rejects negative quantity", () => {
      const cart = new Cart();
      cart.add(mkProduct("a", 1000), 1);
      expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      cart.add(mkProduct("a", 1000), 1);
      expect(() => cart.updateQuantity("a", 1.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("removes all items", () => {
      const cart = new Cart();
      cart.add(mkProduct("a", 1000), 2);
      cart.add(mkProduct("b", 2000), 3);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy of cart lines", () => {
      const cart = new Cart();
      const product = mkProduct("a", 1000);
      cart.add(product, 2);
      const snap = cart.snapshot();
      expect(snap).toHaveLength(1);
      expect(snap[0].product.id).toBe("a");
      expect(snap[0].quantity).toBe(2);

      // Mutating snapshot should not affect cart
      (snap[0] as { quantity: number }).quantity = 99;
      expect(cart.itemCount).toBe(2);
    });
  });

  describe("totals — pricing pipeline", () => {
    it("computes subtotal as sum of unitPriceCents * quantity", () => {
      const cart = new Cart();
      cart.add(mkProduct("a", 1000), 2); // 2000
      cart.add(mkProduct("b", 500), 3); // 1500
      const t = cart.totals();
      expect(t.subtotalCents).toBe(3500);
    });

    it("returns all zeros for empty cart", () => {
      const cart = new Cart();
      const t = cart.totals();
      expect(t).toEqual({
        subtotalCents: 0,
        discountCents: 0,
        taxCents: 0,
        shippingCents: 0,
        totalCents: 0,
      });
    });

    it("applies discount → tax on discounted subtotal → shipping", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(500),
      };
      const tax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(150),
      };
      const shipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(300),
      };

      const cart = new Cart({
        discountPolicy: discount,
        taxCalculator: tax,
        shippingCalculator: shipping,
        region: "US-CA",
      });
      cart.add(mkProduct("a", 1000), 2); // subtotal 2000

      const t = cart.totals();

      // Discount applied to subtotal
      expect(discount.computeDiscountCents).toHaveBeenCalledWith(2000);
      expect(t.discountCents).toBe(500);

      // Tax on discounted subtotal (2000 - 500 = 1500)
      expect(tax.computeTaxCents).toHaveBeenCalledWith(1500, "US-CA");
      expect(t.taxCents).toBe(150);

      // Shipping on discounted subtotal
      expect(shipping.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        1500,
      );
      expect(t.shippingCents).toBe(300);

      // total = discountedSubtotal + tax + shipping = 1500 + 150 + 300
      expect(t.totalCents).toBe(1950);
    });

    it("clamps discount to [0, subtotal]", () => {
      // Discount exceeds subtotal
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(99999),
      };
      const cart = new Cart({ discountPolicy: discount });
      cart.add(mkProduct("a", 1000), 1);
      const t = cart.totals();
      expect(t.discountCents).toBe(1000); // clamped to subtotal
      expect(t.totalCents).toBe(0);
    });

    it("clamps negative discount to 0", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(-500),
      };
      const cart = new Cart({ discountPolicy: discount });
      cart.add(mkProduct("a", 1000), 1);
      const t = cart.totals();
      expect(t.discountCents).toBe(0);
    });

    it("clamps negative tax to 0", () => {
      const tax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ taxCalculator: tax });
      cart.add(mkProduct("a", 1000), 1);
      const t = cart.totals();
      expect(t.taxCents).toBe(0);
    });

    it("clamps negative shipping to 0", () => {
      const shipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ shippingCalculator: shipping });
      cart.add(mkProduct("a", 1000), 1);
      const t = cart.totals();
      expect(t.shippingCents).toBe(0);
    });

    it("uses default seams when no config is provided", () => {
      const cart = new Cart();
      cart.add(mkProduct("a", 1000), 1);
      const t = cart.totals();
      // Defaults: NoDiscountPolicy(0), NoTaxCalculator(0), FreeShippingCalculator(0)
      expect(t.subtotalCents).toBe(1000);
      expect(t.discountCents).toBe(0);
      expect(t.taxCents).toBe(0);
      expect(t.shippingCents).toBe(0);
      expect(t.totalCents).toBe(1000);
    });
  });

  describe("checkout", () => {
    it("returns totals and lines without collaborators", async () => {
      const cart = new Cart();
      cart.add(mkProduct("a", 1000), 2);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(2000);
      expect(result.lines).toHaveLength(1);
      expect(result.lines[0].quantity).toBe(2);
    });

    describe("price refresh", () => {
      it("refreshes prices from PriceFetcher before computing totals", async () => {
        const cart = new Cart();
        cart.add(mkProduct("a", 1000), 2);

        const fetcher: PriceFetcher = {
          fetchPriceCents: vi.fn().mockResolvedValue(1500),
        };

        const result = await cart.checkout({ priceFetcher: fetcher });
        expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("a");
        expect(result.totals.subtotalCents).toBe(3000); // 1500 * 2
        expect(result.lines[0].product.unitPriceCents).toBe(1500);
      });

      it("propagates PriceFetcher failure", async () => {
        const cart = new Cart();
        cart.add(mkProduct("a", 1000), 1);

        const fetcher: PriceFetcher = {
          fetchPriceCents: vi
            .fn()
            .mockRejectedValue(new Error("price service down")),
        };

        await expect(cart.checkout({ priceFetcher: fetcher })).rejects.toThrow(
          "price service down",
        );
      });
    });

    describe("inventory check", () => {
      it("proceeds when inventory is available", async () => {
        const cart = new Cart();
        cart.add(mkProduct("a", 1000), 2);

        const checker: InventoryChecker = {
          check: vi.fn().mockResolvedValue({ available: true }),
        };

        const result = await cart.checkout({ inventoryChecker: checker });
        expect(checker.check).toHaveBeenCalledWith("a", 2);
        expect(result.totals.subtotalCents).toBe(2000);
      });

      it("throws InventoryError when item unavailable", async () => {
        const cart = new Cart();
        cart.add(mkProduct("a", 1000), 5);

        const checker: InventoryChecker = {
          check: vi.fn().mockResolvedValue({
            available: false,
            reason: "discontinued",
          }),
        };

        try {
          await cart.checkout({ inventoryChecker: checker });
          expect.fail("should have thrown");
        } catch (err) {
          expect(err).toBeInstanceOf(InventoryError);
          const invErr = err as InventoryError;
          expect(invErr.productId).toBe("a");
          expect(invErr.requested).toBe(5);
          expect(invErr.message).toBe("discontinued");
        }
      });

      it("throws InventoryError for partial-stock denial", async () => {
        const cart = new Cart();
        cart.add(mkProduct("a", 1000), 10);

        const checker: InventoryChecker = {
          check: vi.fn().mockResolvedValue({
            available: true,
            availableQuantity: 3,
          }),
        };

        try {
          await cart.checkout({ inventoryChecker: checker });
          expect.fail("should have thrown");
        } catch (err) {
          expect(err).toBeInstanceOf(InventoryError);
          const invErr = err as InventoryError;
          expect(invErr.productId).toBe("a");
          expect(invErr.requested).toBe(10);
          expect(invErr.available).toBe(3);
        }
      });

      it("checks inventory for each line and fails on first denial", async () => {
        const cart = new Cart();
        cart.add(mkProduct("a", 1000), 1);
        cart.add(mkProduct("b", 2000), 1);

        const checker: InventoryChecker = {
          check: vi
            .fn()
            .mockResolvedValueOnce({ available: true })
            .mockResolvedValueOnce({ available: false }),
        };

        await expect(
          cart.checkout({ inventoryChecker: checker }),
        ).rejects.toThrow(InventoryError);
        expect(checker.check).toHaveBeenCalledTimes(2);
      });
    });

    describe("async tax", () => {
      it("uses AsyncTaxRateProvider for tax computation", async () => {
        const discount: DiscountPolicy = {
          computeDiscountCents: vi.fn().mockReturnValue(200),
        };
        const shipping: ShippingCalculator = {
          computeShippingCents: vi.fn().mockReturnValue(500),
        };

        const cart = new Cart({
          discountPolicy: discount,
          shippingCalculator: shipping,
          region: "US-CA",
        });
        cart.add(mkProduct("a", 1000), 2); // subtotal 2000

        const asyncTaxProvider: AsyncTaxRateProvider = {
          getRate: vi.fn().mockResolvedValue(0.1),
        };

        const result = await cart.checkout({ asyncTaxProvider });

        // discount: 200, discounted subtotal: 1800
        // tax: 10% of 1800 = 180
        // shipping: 500
        expect(result.totals.subtotalCents).toBe(2000);
        expect(result.totals.discountCents).toBe(200);
        expect(result.totals.taxCents).toBe(180);
        expect(result.totals.shippingCents).toBe(500);
        expect(result.totals.totalCents).toBe(1800 + 180 + 500);
        expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
      });

      it("propagates async tax provider failure", async () => {
        const cart = new Cart();
        cart.add(mkProduct("a", 1000), 1);

        const asyncTaxProvider: AsyncTaxRateProvider = {
          getRate: vi
            .fn()
            .mockRejectedValue(new Error("tax service unavailable")),
        };

        await expect(
          cart.checkout({ asyncTaxProvider }),
        ).rejects.toThrow("tax service unavailable");
      });
    });

    describe("full pipeline with all collaborators", () => {
      it("refreshes prices, checks inventory, then computes async totals", async () => {
        const discount: DiscountPolicy = {
          computeDiscountCents: vi.fn().mockReturnValue(100),
        };
        const shipping: ShippingCalculator = {
          computeShippingCents: vi.fn().mockReturnValue(250),
        };
        const cart = new Cart({
          discountPolicy: discount,
          shippingCalculator: shipping,
          region: "FR",
        });
        cart.add(mkProduct("a", 1000), 2);

        const fetcher: PriceFetcher = {
          fetchPriceCents: vi.fn().mockResolvedValue(1200),
        };
        const checker: InventoryChecker = {
          check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
        };
        const asyncTaxProvider: AsyncTaxRateProvider = {
          getRate: vi.fn().mockResolvedValue(0.2),
        };

        const result = await cart.checkout({
          priceFetcher: fetcher,
          inventoryChecker: checker,
          asyncTaxProvider,
        });

        // refreshed price: 1200 * 2 = 2400
        expect(result.totals.subtotalCents).toBe(2400);
        // discount: 100, discounted: 2300
        expect(result.totals.discountCents).toBe(100);
        // tax: 20% of 2300 = 460
        expect(result.totals.taxCents).toBe(460);
        expect(result.totals.shippingCents).toBe(250);
        // total = 2300 + 460 + 250 = 3010
        expect(result.totals.totalCents).toBe(3010);
        expect(result.lines[0].product.unitPriceCents).toBe(1200);
      });
    });
  });
