          expect(err).toBeInstanceOf(InventoryError);
          const invErr = err as InventoryError;
          expect(invErr.productId).toBe("a");
          expect(invErr.requested).toBe(5);
          expect(invErr.message).toBe("discontinued");
        }
      });

      it("throws InventoryError for partial-stock denial", async () => {
        const cart = new Cart();
        cart.add(mkProduct("a", 1000), 10);

        const checker: InventoryChecker = {
          check: vi.fn().mockResolvedValue({
            available: true,
            availableQuantity: 3,
          }),
        };

        try {
          await cart.checkout({ inventoryChecker: checker });
          expect.fail("should have thrown");
        } catch (err) {
          expect(err).toBeInstanceOf(InventoryError);
          const invErr = err as InventoryError;
          expect(invErr.productId).toBe("a");
          expect(invErr.requested).toBe(10);
          expect(invErr.available).toBe(3);
        }
      });

      it("checks inventory for each line and fails on first denial", async () => {
        const cart = new Cart();
        cart.add(mkProduct("a", 1000), 1);
        cart.add(mkProduct("b", 2000), 1);

        const checker: InventoryChecker = {
          check: vi
            .fn()
            .mockResolvedValueOnce({ available: true })
            .mockResolvedValueOnce({ available: false }),
        };

        await expect(
          cart.checkout({ inventoryChecker: checker }),
        ).rejects.toThrow(InventoryError);
        expect(checker.check).toHaveBeenCalledTimes(2);
      });
    });

    describe("async tax", () => {
      it("uses AsyncTaxRateProvider for tax computation", async () => {
        const discount: DiscountPolicy = {
          computeDiscountCents: vi.fn().mockReturnValue(200),
        };
        const shipping: ShippingCalculator = {
          computeShippingCents: vi.fn().mockReturnValue(500),
        };

        const cart = new Cart({
          discountPolicy: discount,
          shippingCalculator: shipping,
          region: "US-CA",
        });
        cart.add(mkProduct("a", 1000), 2); // subtotal 2000

        const asyncTaxProvider: AsyncTaxRateProvider = {
          getRate: vi.fn().mockResolvedValue(0.1),
        };

        const result = await cart.checkout({ asyncTaxProvider });

        // discount: 200, discounted subtotal: 1800
        // tax: 10% of 1800 = 180
        // shipping: 500
        expect(result.totals.subtotalCents).toBe(2000);
        expect(result.totals.discountCents).toBe(200);
        expect(result.totals.taxCents).toBe(180);
        expect(result.totals.shippingCents).toBe(500);
        expect(result.totals.totalCents).toBe(1800 + 180 + 500);
        expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
      });

      it("propagates async tax provider failure", async () => {
        const cart = new Cart();
        cart.add(mkProduct("a", 1000), 1);

        const asyncTaxProvider: AsyncTaxRateProvider = {
          getRate: vi
            .fn()
            .mockRejectedValue(new Error("tax service unavailable")),
        };

        await expect(
          cart.checkout({ asyncTaxProvider }),
        ).rejects.toThrow("tax service unavailable");
      });
    });

    describe("full pipeline with all collaborators", () => {
      it("refreshes prices, checks inventory, then computes async totals", async () => {
        const discount: DiscountPolicy = {
          computeDiscountCents: vi.fn().mockReturnValue(100),
        };
        const shipping: ShippingCalculator = {
          computeShippingCents: vi.fn().mockReturnValue(250),
        };
        const cart = new Cart({
          discountPolicy: discount,
          shippingCalculator: shipping,
          region: "FR",
        });
        cart.add(mkProduct("a", 1000), 2);

        const fetcher: PriceFetcher = {
          fetchPriceCents: vi.fn().mockResolvedValue(1200),
        };
        const checker: InventoryChecker = {
          check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
        };
        const asyncTaxProvider: AsyncTaxRateProvider = {
          getRate: vi.fn().mockResolvedValue(0.2),
        };

        const result = await cart.checkout({
          priceFetcher: fetcher,
          inventoryChecker: checker,
          asyncTaxProvider,
        });

        // refreshed price: 1200 * 2 = 2400
        expect(result.totals.subtotalCents).toBe(2400);
        // discount: 100, discounted: 2300
        expect(result.totals.discountCents).toBe(100);
        // tax: 20% of 2300 = 460
        expect(result.totals.taxCents).toBe(460);
        expect(result.totals.shippingCents).toBe(250);
        // total = 2300 + 460 + 250 = 3010
        expect(result.totals.totalCents).toBe(3010);
        expect(result.lines[0].product.unitPriceCents).toBe(1200);
      });
    });
  });
});
