import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const mkLine = (
  id: string,
  weightGrams: number,
  quantity: number,
): CartLine => ({
  product: { id, name: id, unitPriceCents: 1000, weightGrams },
  quantity,
});

const mkLineNoWeight = (id: string, quantity: number): CartLine => ({
  product: { id, name: id, unitPriceCents: 1000 },
  quantity,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for non-empty cart", () => {
    expect(calc.computeShippingCents([mkLine("a", 500, 2)], 5000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(5.5)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 99.5)).toThrow(RangeError);
    });

    it("accepts zero flatCents", () => {
      expect(() => new FlatShippingCalculator(0)).not.toThrow();
    });

    it("accepts zero freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns flat fee for non-empty cart below threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([mkLine("a", 100, 1)], 4999)).toBe(599);
    });

    it("returns 0 when subtotal meets freeOver threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([mkLine("a", 100, 1)], 5000)).toBe(0);
    });

    it("returns 0 when subtotal exceeds freeOver threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([mkLine("a", 100, 1)], 10000)).toBe(0);
    });

    it("returns flat fee when no threshold is set", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([mkLine("a", 100, 1)], 99999)).toBe(599);
    });

    it("returns 0 for empty cart", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([], 0)).toBe(0);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets list", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with zero upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 500 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: -1, costCents: 500 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with non-integer costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: 5.5 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 5000, costCents: 1200 },
      ],
      2000,
    );

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 for cart with zero-weight items", () => {
      expect(
        calc.computeShippingCents([mkLineNoWeight("a", 3)], 5000),
      ).toBe(0);
    });

    it("selects first bracket for weight within it", () => {
      // 250g item, 1 qty → 250g ≤ 500 → 300
      expect(calc.computeShippingCents([mkLine("a", 250, 1)], 5000)).toBe(300);
    });

    it("selects bracket at boundary (weight == upToGrams)", () => {
      // exactly 500g → 300
      expect(calc.computeShippingCents([mkLine("a", 500, 1)], 5000)).toBe(300);
    });

    it("selects next bracket when weight exceeds boundary", () => {
      // 501g → next bracket (≤2000) → 700
      expect(calc.computeShippingCents([mkLine("a", 501, 1)], 5000)).toBe(700);
    });

    it("selects highest bracket for weight at its boundary", () => {
      // 5000g → 1200
      expect(calc.computeShippingCents([mkLine("a", 5000, 1)], 5000)).toBe(1200);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      // 5001g → overflow → 2000
      expect(calc.computeShippingCents([mkLine("a", 5001, 1)], 5000)).toBe(2000);
    });

    it("uses highest bracket cost as overflow when overflowCostCents not set", () => {
      const calcNoOverflow = new WeightBasedShippingCalculator([
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 600 },
      ]);
      // 2000g > 1000 → fallback to last bracket cost = 600
      expect(
        calcNoOverflow.computeShippingCents([mkLine("a", 2000, 1)], 5000),
      ).toBe(600);
    });

    it("sums weight across multiple lines", () => {
      // line a: 300g * 2 = 600, line b: 400g * 1 = 400 → total 1000g ≤ 2000 → 700
      const lines = [mkLine("a", 300, 2), mkLine("b", 400, 1)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(700);
    });

    it("sorts brackets regardless of input order", () => {
      const unordered = new WeightBasedShippingCalculator([
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 500, costCents: 300 },
      ]);
      // 400g ≤ 500 → 300 (sorted correctly)
      expect(
        unordered.computeShippingCents([mkLine("a", 400, 1)], 5000),
      ).toBe(300);
    });
  });
});

